const tasks=()=>catalog.tasks;
const now=()=>new Date().toISOString();
function el(tag,props={},...children){const n=document.createElement(tag);for(const [key,value]of Object.entries(props)){if(key==='class')n.className=value;else if(key==='text')n.textContent=value;else if(key.startsWith('on'))n.addEventListener(key.slice(2),value);else if(key==='checked'||key==='disabled')n[key]=value;else n.setAttribute(key,value);}for(const child of children.flat(Infinity)){if(child!==null&&child!==undefined)n.append(child.nodeType?child:document.createTextNode(String(child)));}return n;}
function toast(message,error=false){$('toast').textContent=message;$('toast').hidden=false;$('toast').style.background=error?'#8a3935':'#173e42';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6500);}
function errorMessage(error){return String(error?.message||error);}
