function statusText(value){return t(value||'unreviewed');}
function normalizeState(value,id){const base=createTask(id);return {...base,...value,id,decision:{status:'unreviewed',answers:{},note:'',...value?.decision},marks:value?.marks||[],selections:value?.selections||[],segments:value?.segments||[],view:value?.view||{}};}
function renderStatic(){document.documentElement.lang=lang;$('saveStatus').textContent=t($('saveStatus').classList.contains('error')?'saveError':store?.status().state||'saved');for(const n of document.querySelectorAll('[data-i18n]'))n.textContent=t(n.dataset.i18n);$('language').value=lang;const filter=$('cellFilter').value;$('cellFilter').replaceChildren(el('option',{value:'',text:t('allCells')}),...catalog.recipients.map(r=>el('option',{value:r.id,text:r.id})));$('cellFilter').value=filter;const category=$('markCategory').value;$('markCategory').replaceChildren(...categories.map(x=>el('option',{value:x,text:t(x)})));if(category)$('markCategory').value=category;viewer?.setLanguage(lang);renderTaskList();if(current)renderCurrent();}
function renderTaskList(){renderShell(catalog,current,lang);const filter=$('cellFilter').value,search=$('taskSearch').value.trim().toLowerCase();let annotated=0;for(const value of stateById.values())if(value.marks.length||value.selections.length||value.decision.note)annotated++;$('progress').textContent=`${annotated} / ${tasks().length} · ${t('annotatedTasks')}`;$('taskList').replaceChildren(...tasks().filter(x=>(!filter||x.recipientId===filter)&&(!search||[x.id,loc(x.title),loc(x.question)].join(' ').toLowerCase().includes(search))).map(x=>{const count=stateById.get(x.id)?.marks.length||0;return el('button',{class:`task-item${current?.id===x.id?' active':''}`,'data-task':x.id,onclick:()=>switchTask(x.id)},el('span',{class:'task-no',text:x.id}),el('span',{class:'task-name',text:loc(x.title)}),el('span',{class:'task-state',text:count?`${count} ${t('marks')}`:t('noMarks')}));}));}
function history(){if(!histories.has(task.id))histories.set(task.id,{undo:[],redo:[]});return histories.get(task.id);}
function remember(){const h=history();h.undo.push(clone(task));if(h.undo.length>80)h.undo.shift();h.redo=[];}
function mutate(fn,{render=true,undo=true}={}){if(!task)return;if(undo)remember();fn(task);task.updatedAt=now();stateById.set(task.id,task);scheduleSave(task);if(render){renderEvidence();renderSegments();renderTaskList();syncMarks();}updateUndo();}
function updateUndo(){const h=task?history():{undo:[],redo:[]};$('undo').disabled=!h.undo.length;$('redo').disabled=!h.redo.length;}
function restoreHistory(direction){const h=history(),from=h[direction],to=h[direction==='undo'?'redo':'undo'];if(!from.length)return;to.push(clone(task));const draftingId=draft?.id||activeMarkId,old=from.pop();old.revision=task.revision;task=old;draft=clone(task.marks.find(mark=>mark.id===draftingId&&mark.draft)||null);if(!task.marks.some(mark=>mark.id===activeMarkId))activeMarkId=null;stateById.set(task.id,task);scheduleSave(task);renderCurrent();applyViewer();}
function scheduleSave(value){const id=value.id;clearTimeout(saveTimers.get(id));saveTimers.set(id,setTimeout(()=>{saveTimers.delete(id);persist(id).catch(handleError);},160));$('saveStatus').textContent=t('saving');}
async function persist(id){const value=stateById.get(id);if(!value)return;let result;try{result=await store.save(clone(value));}catch(error){$('saveStatus').textContent=t('saveError');$('saveStatus').classList.add('error');throw error;}const latest=stateById.get(id);if(latest)latest.revision=result.revision;}
async function saveAll(){if(editor&&$('editorDialog').open){commitEditor();if(editor)throw new Error(t('geometryTooShort'));}if(draft?.pointsNm.length)saveDraft();const pending=[...saveTimers.keys()];for(const id of pending){clearTimeout(saveTimers.get(id));saveTimers.delete(id);await persist(id);}if(store.status().state==='error')await store.retry();else await store.flush();}
function saveDraft(){if(!draft?.pointsNm.length)return;const mark={...draft,label:draft.label||`${t(draft.kind)} · ${t('in_progress')}`,draft:true,updatedAt:now()};mutate(s=>{const existing=s.marks.findIndex(m=>m.id===mark.id);if(existing>=0)s.marks[existing]=clone(mark);else s.marks.push(clone(mark));});draft=null;syncMarks();$('draftHint').textContent=t('draftRetained');}
async function switchTask(id){
  const next=tasks().find(x=>x.id===id);if(!next)return;
  const generation=++taskGeneration;
  if(current?.id===id){applying=false;return;}
  try{
    await saveAll();if(generation!==taskGeneration)return;
    const nextState=stateById.get(id)||normalizeState(await store.load(id),id);
    if(generation!==taskGeneration)return;
    applying=true;current=next;task=nextState;stateById.set(id,task);
    checked.clear();draft=null;activeContact=null;activeMarkId=null;tool='navigate';viewer.setTool(tool);
    document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));
    const url=new URL(location);url.searchParams.set('task',id);historyReplace(url);
    renderCurrent();renderTaskList();$('contactResults').replaceChildren();await applyViewer();
  }catch(error){handleError(error);}finally{if(generation===taskGeneration)applying=false;}
}
function historyReplace(url){window.history.replaceState(null,'',url);}
async function applyViewer(){const definition=current,state=task;await viewer.setTask(definition,state.view,state.segments);if(current!==definition||task!==state||viewer.task?.id!==definition.id)return;syncMarks();renderView(viewer.getView());}
function renderCurrent(){if(!current)return;$('taskMeta').textContent=`${current.recipientId} · ${tasks().indexOf(current)+1} / ${tasks().length} · release661`;$('taskTitle').textContent=loc(current.title);$('taskQuestion').textContent=loc(current.question);const missing=current.coverage?.status==='no-prepared-crop'||current.coverage?.hasExistingCrop===false||current.coverage?.existingCropCount===0;$('coverage').textContent=`${t(missing?'missingCoverage':'coverageNote')} ${t('sourceUnresolved')}`;$('prevTask').disabled=tasks().indexOf(current)===0;$('nextTask').disabled=tasks().indexOf(current)===tasks().length-1;renderMarkupGuide();renderEvidence();renderSegments();renderSource();renderAnchors();renderView(viewer.getView());updateUndo();}
function renderAnchors(){const anchors=current.navigationAnchors||[];$('anchorSelect').replaceChildren(el('option',{value:'',text:lang==='ru'?'Исходные якоря':'Source anchors'}),...anchors.map((a,i)=>el('option',{value:String(i),text:loc(a.label)||a.id||a.kind||String(i+1)})));}
function renderMarkupGuide(){
 const guides={identity:['Обведите мембрану сомы и отметьте участки, по которым прослеживается её продолжение. Различайте плазматическую мембрану, органеллы и соседние структуры.','Outline the soma membrane and mark the sections used to follow its continuation. Distinguish plasma membrane, organelles and neighboring structures.'],origin_route:['Проследите видимую ветвь открытой трассой. На каждом срезе создавайте отдельную метку; у предполагаемого соединения поставьте стрелку и запишите, что видно и что остаётся неясным.','Follow the visible branch with an open trace. Create a separate mark on each section; point to a possible attachment with an arrow and note what is visible and uncertain.'],branch_relation:['Отметьте сравниваемые ветви разными цветами и названиями. Укажите возможную общую точку ветвления и сохраните виды соседних срезов.','Mark the compared branches with distinct colors and names. Indicate a possible shared branch point and save views of neighboring sections.'],compartment_cut:['Раздельно подпишите родительскую и дочернюю ветви, укажите место возможного прикрепления. Пробелы в покрытии выделите областью и опишите.','Label parent and child branches separately and indicate the possible attachment. Outline gaps in coverage and describe them.'],boundary:['Обведите видимый участок границы. Отдельно отмечайте плазматическую мембрану, органеллы и мембрану соседней структуры; запишите неоднозначные участки.','Outline the visible boundary. Distinguish plasma membrane, organelles and neighboring membranes; note ambiguous sections.'],damage:['Выделите повреждённую область рамкой или эллипсом, отметьте последние видимые участки до и после пробела на отдельных срезах. Не соединяйте их непрерывной трассой через пробел.','Outline damage with a box or ellipse. Mark the last visible portions before and after the gap on separate sections; do not bridge it with a continuous trace.']};
 $('taskMarkupGuide').textContent=(guides[current.category]||guides.origin_route)[lang==='en'?1:0];$('taskNote').value=task.decision.note||'';renderInspector();updateToolHint();
}
function renderSource(){const r=catalog.recipients.find(x=>x.id===current.recipientId);$('sourceDetails').replaceChildren(el('p',{text:`release661 root: ${current.rootRelease661||r?.rootRelease661}`}),el('p',{text:t('sourceUnresolved')}),el('p',{text:`${catalog.coordinateConvention}; nm = (local + offset) × resolution`}),el('p',{text:`Catalog SHA-256: ${catalog.catalogHash}`}),el('details',{},el('summary',{text:'Provenance JSON'}),el('pre',{text:JSON.stringify({anchorNm:current.anchorNm,coverage:current.coverage,sourceRefs:current.sourceRefs,mapping:r?.mapping},null,2)})),el('button',{text:t('copyLink'),onclick:async()=>{await navigator.clipboard.writeText(location.href);toast(t('copied'));}}));}
function renderView(view){if(!view?.centerNm)return;renderShellView(view);$('plane').value=(view.plane||'xy').toUpperCase();const axis={xy:2,xz:1,yz:0}[view.plane||'xy'];$('depth').step=[8,8,40][axis];$('depth').value=view.centerNm[axis];$('coordinates').textContent=`${view.plane?.toUpperCase()} · ${view.centerNm.map(x=>Math.round(x*100)/100).join(', ')} nm${view.nativeOblique?(lang==='ru'?' · NG: косой вид; ЭМ: ортогональный срез':' · NG: oblique view; EM: orthogonal plane'):''}`;$('draftHint').textContent=draft?`${t('draftMark')} · ${draft.pointsNm.length}`:'';if(task&&$('evidenceFilter').value==='current')renderEvidence(false);updateToolHint();}
function onViewChange(view,metadata={}){if(booting||!task||viewer?.task?.id!==task.id||metadata.taskId&&metadata.taskId!==task.id||exportBusy)return;if(draft?.pointsNm.length){const axis={xy:2,xz:1,yz:0}[markPlane(draft)];if(markPlane(draft)!==view.plane||Math.abs(draft.pointsNm[0][axis]-view.centerNm[axis])>0.01)saveDraft();}renderView(view);task.view=clone(view);task.updatedAt=now();stateById.set(task.id,task);scheduleSave(task);}
function onSegmentsChange(segments,metadata={}){if(booting||!task||viewer?.task?.id!==task.id||metadata.taskId&&metadata.taskId!==task.id||exportBusy)return;mutate(s=>s.segments=clone(segments),{undo:!metadata.initialization,render:false});renderSegments();}
function setTool(value){if(draft?.pointsNm.length)saveDraft();tool=value;viewer.setTool(value);document.querySelectorAll('[data-tool]').forEach(button=>{button.classList.toggle('active',button.dataset.tool===value);button.setAttribute('aria-pressed',String(button.dataset.tool===value));});updateToolHint();}
function updateToolHint(){
 const hints={navigate:['Перетаскивайте изображение. Колесо: масштаб; Shift и колесо: срез.','Drag to pan. Wheel: zoom; Shift and wheel: section.'],select:['Нажмите на метку. Перетаскивайте её целиком или за белые узлы. E: заметка; Delete: удалить.','Click a mark, then drag its body or white handles. E: note; Delete: delete.'],point:['Щёлкните по изображению, затем добавьте название и заметку.','Click the image, then add a label and note.'],trace:['Щёлкайте вдоль ветви. Enter или «Завершить трассу» добавит заметку.','Click along the branch. Enter or Finish trace opens its note.'],freehand:['Удерживайте кнопку мыши и обведите участок. Отпустите, чтобы добавить заметку.','Hold and draw around a feature. Release to add a note.'],arrow:['Протяните стрелку от подписи к интересующему участку. Отпустите для заметки.','Drag from the arrow tail toward the feature. Release to add a note.'],ellipse:['Протяните от одного угла области к противоположному.','Drag between opposite corners of the region.'],roi:['Протяните рамку вокруг интересующей области.','Drag a box around the region.'],distance:['Протяните между двумя точками для измерения в микрометрах.','Drag between two points to measure in micrometers.']};
 const shortcuts={navigate:'H',select:'V',arrow:'A',point:'P',trace:'T',freehand:'F',roi:'B',ellipse:'O',distance:'D'};for(const button of document.querySelectorAll('[data-tool]'))button.title=`${t(button.dataset.tool)} · ${shortcuts[button.dataset.tool]}`;$('toolHint').textContent=(hints[tool]||hints.navigate)[lang==='en'?1:0];$('finishMark').disabled=!draft?.pointsNm.length;$('cancelMark').disabled=!draft;
}
function syncMarks(){if(task)viewer.setOverlays($('showMarks').checked?task.marks:[],activeMarkId);}
function markOnSlice(mark){const v=viewer.getView(),axis={xy:2,xz:1,yz:0}[v.plane];return markPlane(mark)===v.plane&&mark.pointsNm.every(point=>Math.abs(point[axis]-v.centerNm[axis])<[8,8,40][axis]/2);}
function selectedMark(){return task?.marks.find(mark=>mark.id===activeMarkId);}
function selectMark(id){activeMarkId=task?.marks.some(mark=>mark.id===id)?id:null;renderEvidence();syncMarks();}
function markStyle(){return {color:$('markColor').value,strokeWidth:Number($('markWidth').value)||3};}
function makeMark(kind,points,plane,binding){return {id:newId(),kind,category:$('markCategory').value,label:`${t(kind)} ${task.marks.length+1}`,note:'',visible:true,...markStyle(),pointsNm:clone(points),plane,view:clone(viewer.getView()),sourceBinding:{catalogHash:catalog.catalogHash,sourceHash:catalog.sourceHash,coordinateConvention:'integer-sample',...binding},createdAt:now(),updatedAt:now()};}
function onMark(event){if(!task||exportBusy||event.taskId&&event.taskId!==task.id)return;if(draft?.pointsNm.length)saveDraft();draft={...makeMark(event.kind,event.pointsNm,event.plane,event.sourceBinding),draft:true};activeMarkId=draft.id;mutate(state=>state.marks.push(clone(draft)));openEditor('draft',draft);updateToolHint();}
function onMarkEdit(event){if(!task||exportBusy||event.taskId!==task.id)return;const mark=task.marks.find(mark=>mark.id===event.id);if(!mark)return;const next={...clone(mark),pointsNm:clone(event.pointsNm),geometryEdited:true,updatedAt:now()};try{validateMarkGeometry(next);}catch(error){return toast(error.message,true);}activeMarkId=mark.id;mutate(state=>{state.marks[state.marks.findIndex(item=>item.id===mark.id)]=next;});}
function renderInspector(){const mark=selectedMark();$('activeMarkFields').hidden=!mark;$('inspectorEmpty').hidden=!!mark;$('activeMarkKind').textContent=mark?t(mark.kind):'';if(!mark)return;$('activeMarkLabel').value=mark.label;$('activeMarkNote').value=mark.note;$('activeMarkColor').value=mark.color||'#ffd166';$('activeMarkWidth').value=mark.strokeWidth||2;$('activeMarkCategory').replaceChildren(...categories.map(category=>el('option',{value:category,text:t(category)})));if(!categories.includes(mark.category))$('activeMarkCategory').append(el('option',{value:mark.category,text:mark.category}));$('activeMarkCategory').value=mark.category;$('activeMarkPosition').textContent=`${markPlane(mark).toUpperCase()} · ${mark.pointsNm[0].join(', ')} nm${markOnSlice(mark)?'':' · '+t('onOtherSlice')}`;}
function editActive(field,value,{undo=true}={}){const mark=selectedMark();if(!mark)return;mutate(state=>{const item=state.marks.find(item=>item.id===mark.id);item[field]=value;item.updatedAt=now();},{render:false,undo});if(draft?.id===mark.id)draft=clone(selectedMark());syncMarks();renderEvidence(false);}
function removeMark(id){if(!task?.marks.some(mark=>mark.id===id))return;if(draft?.id===id)draft=null;if(activeMarkId===id)activeMarkId=null;checked.delete(id);mutate(state=>{state.marks=state.marks.filter(mark=>mark.id!==id);state.selections.forEach(selection=>selection.markIds=selection.markIds.filter(markId=>markId!==id));});updateToolHint();}
async function downloadMarkedImage(){try{await saveAll();const out=await viewer.exportPlane(),image=out.files.find(file=>file.name==='annotated-physical.png');blobDownload(image.blob,`${task.id}-${viewer.getView().plane}-marked.png`);}catch(error){handleError(error);}}
function onPoint(event){if(!['point','trace'].includes(tool)||!task||event.taskId&&event.taskId!==task.id)return;const point=event.pointNm||event.point_nm||event.nm;if(!Array.isArray(point)||point.length!==3||!point.every(Number.isFinite))return;const plane=event.plane||viewer.getView().plane;if(draft&&(markPlane(draft)!==plane||Math.abs(draft.pointsNm[0][{xy:2,xz:1,yz:0}[plane]]-point[{xy:2,xz:1,yz:0}[plane]])>.01))saveDraft();if(!draft)draft=makeMark(tool,[],plane,event.sourceBinding);draft.pointsNm.push(point.map(Number));draft.draft=true;activeMarkId=draft.id;mutate(state=>{const index=state.marks.findIndex(mark=>mark.id===draft.id);if(index<0)state.marks.push(clone(draft));else state.marks[index]=clone(draft);});renderView(viewer.getView());updateToolHint();if(tool==='point')openEditor('draft',draft);}
function beginEdit(collection,item){openEditor(collection,clone(item));}
function openEditor(collection,item){item=clone(item);editor={collection,item};if(item.pointsNm)activeMarkId=item.id;$('editorTitle').textContent=t(collection==='segments'?'objects':item.kind||'selection');$('itemLabel').value=item.label||'';$('itemNote').value=item.note||'';$('itemVisible').checked=item.visible!==false;$('markStyleFields').hidden=!item.pointsNm;$('itemColor').value=item.color||'#ffd166';$('itemLineWidth').value=item.strokeWidth||3;$('itemCategory').replaceChildren(...categories.map(category=>el('option',{value:category,text:t(category)})));if(item.category&&!categories.includes(item.category))$('itemCategory').append(el('option',{value:item.category,text:item.category}));$('itemCategory').value=item.category||'other';$('geometryEditor').replaceChildren();if(item.pointsNm?.length){$('geometryEditor').append(el('p',{class:'muted',text:t('editGeometry')}));item.pointsNm.forEach((point,index)=>{const row=el('div',{class:'vertex-row'});point.forEach((v,axis)=>row.append(el('input',{type:'number',value:v,step:'any','aria-label':`${index+1} ${'XYZ'[axis]}`,onchange:e=>{item.pointsNm[index][axis]=Number(e.target.value);item.geometryEdited=true;}})));row.append(el('button',{type:'button',text:'×',onclick:()=>{if(item.pointsNm.length>1){item.label=$('itemLabel').value;item.note=$('itemNote').value;item.visible=$('itemVisible').checked;item.color=$('itemColor').value;item.strokeWidth=Number($('itemLineWidth').value);item.category=$('itemCategory').value;item.pointsNm.splice(index,1);openEditor(collection,item);}}}));$('geometryEditor').append(row);});}if(!$('editorDialog').open)$('editorDialog').showModal();}
function commitEditor(){if(!editor)return;const {collection,item}=editor;item.label=$('itemLabel').value.trim()||t(item.kind||'savedView');item.note=$('itemNote').value;item.visible=$('itemVisible').checked;item.updatedAt=now();if(item.pointsNm?.some(p=>p.some(x=>!Number.isFinite(x))))return toast('Invalid coordinates',true);if(item.pointsNm?.length){const axis={xy:2,xz:1,yz:0}[markPlane(item)];if(item.pointsNm.some(p=>Math.abs(p[axis]-item.pointsNm[0][axis])>1e-6))return toast(lang==='ru'?'Метка должна оставаться в одном срезе.':'A mark must stay within one section.',true);}if(item.kind==='trace'&&item.pointsNm.length<2)return toast(lang==='ru'?'Трассе нужны минимум две точки.':'A trace needs at least two points.',true);item.draft=false;if(item.pointsNm){item.color=$('itemColor').value;item.strokeWidth=Number($('itemLineWidth').value);item.category=$('itemCategory').value;if(item.geometryEdited)item.pointsNm=item.pointsNm.map(point=>point.map((n,i)=>Math.round(n/[8,8,40][i])*[8,8,40][i]));try{validateMarkGeometry(item);}catch(error){return toast(error.message,true);}}if(collection==='draft'){mutate(s=>{const i=s.marks.findIndex(m=>m.id===item.id);if(i<0)s.marks.push(clone(item));else s.marks[i]=clone(item);});draft=null;}else mutate(s=>{const arr=s[collection],i=arr.findIndex(x=>x.id===item.id);if(i>=0)arr[i]=clone(item);else arr.push(clone(item));});$('editorDialog').close();editor=null;renderEvidence();updateToolHint();syncMarks();viewer.updateSegments(task.segments);renderView(viewer.getView());}
