 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveAll().then(()=>toast(t('saved'))).catch(handleError);}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA'].includes(e.target.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();restoreHistory(e.shiftKey?'redo':'undo');}});
 document.addEventListener('keydown',event=>{if(event.ctrlKey||event.metaKey||event.altKey||['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)||document.querySelector('dialog[open]')||event.target.closest('#surfaceStage'))return;const key=event.key.toLowerCase(),keys={v:'select',a:'arrow',p:'point',t:'trace',f:'freehand',b:'roi',o:'ellipse',d:'distance',h:'navigate'};if(keys[key]){event.preventDefault();setTool(keys[key]);}else if(key==='enter'&&draft){event.preventDefault();openEditor('draft',draft);}else if(key==='delete'&&selectedMark()){event.preventDefault();removeMark(activeMarkId);}else if(key==='e'&&selectedMark()){event.preventDefault();beginEdit('marks',selectedMark());}else if(key==='escape'&&draft){removeMark(draft.id);draft=null;}});
