async function init(){const response=await fetch('data/catalog.json');if(!response.ok)throw new Error(`Catalog: ${response.status}`);catalog=await response.json();store=await openStore(catalog);store.onStatus(status=>{$('saveStatus').textContent=t(status.state==='error'?'saveError':status.state);$('saveStatus').classList.toggle('error',status.state==='error');});for(const value of await store.all())stateById.set(value.id,normalizeState(value,value.id));await loadAssets();viewer=new ReviewViewer({canvas:$('emCanvas'),frame:$('ngFrame'),status:value=>$('imageStatus').textContent=typeof value==='string'?value.message||value:String(value?.message||value?.state||''),onViewChange,onPoint,onMark,onMarkSelect:selectMark,onMarkEdit,onSegmentsChange,onSave:()=>saveAll().catch(handleError)});await installFamiliarShell(viewer,{sourceHash:catalog.sourceHash,switchTask,editSegment:segment=>beginEdit('segments',segment)});bind();renderStatic();const id=new URL(location).searchParams.get('task');booting=false;window.ReviewApp={get catalog(){return catalog;},get task(){return task;},get current(){return current;},viewer,store,saveAll,switchTask,createExport,parseImport,get states(){return [...stateById.values()];}};await switchTask(tasks().some(x=>x.id===id)?id:tasks()[0].id);$('saveStatus').textContent=t('saved');}
init().catch(error=>{$('taskTitle').textContent=lang==='ru'?'Не удалось открыть проект':'Unable to open project';$('taskQuestion').textContent=errorMessage(error);handleError(error);});
